import { immutableJson } from "../kernel/canonical-json.js";
import { ConflictError, PolicyError, ValidationError } from "../kernel/errors.js";
import {
  enumValue,
  requiredString,
  uniqueStrings
} from "../kernel/validation.js";

export const RISK_CLASSES = Object.freeze(["A0", "A1", "A2", "A3", "A4"]);
export const SENSITIVITY_CLASSES = Object.freeze([
  "public",
  "internal",
  "confidential",
  "restricted"
]);

const RISK_RANK = Object.freeze(
  Object.fromEntries(RISK_CLASSES.map((riskClass, index) => [riskClass, index]))
);

const DEFAULT_ACTIONS = Object.freeze([
  {
    type: "work.intake.analyze",
    capability: "work:intake",
    minimumRiskClass: "A0",
    description: "Analyze a bounded work request."
  },
  {
    type: "operations.release.assess",
    capability: "operations:assess",
    minimumRiskClass: "A0",
    description: "Assess internal software-change readiness."
  },
  {
    type: "marketing.release.draft",
    capability: "marketing:draft",
    minimumRiskClass: "A1",
    description: "Prepare an internal, unpublished communication draft."
  },
  {
    type: "executive.release.synthesize",
    capability: "work:synthesize",
    minimumRiskClass: "A0",
    description: "Synthesize internal evidence into a recommendation."
  },
  {
    type: "specialist.analysis",
    capability: "work:specialist",
    minimumRiskClass: "A0",
    description: "Perform a bounded specialist analysis."
  },
  {
    type: "connector.reference.read",
    capability: "connector:read:reference",
    minimumRiskClass: "A1",
    description:
      "Prepare a bounded read-only reference request under a dry-run connector contract."
  },
  {
    type: "connector.reversible.write",
    capability: "connector:write:reversible",
    minimumRiskClass: "A2",
    description: "Perform a registered, bounded and reversible connector write."
  },
  {
    type: "email.send",
    capability: "email:send",
    minimumRiskClass: "A3",
    description: "Send an external email."
  },
  {
    type: "content.publish",
    capability: "content:publish",
    minimumRiskClass: "A3",
    description: "Publish content externally."
  },
  {
    type: "contract.sign",
    capability: "contract:sign",
    minimumRiskClass: "A3",
    description: "Create a binding contractual action."
  },
  {
    type: "payment.execute",
    capability: "payment:execute",
    minimumRiskClass: "A3",
    description: "Execute a financial payment."
  },
  {
    type: "personnel.decide",
    capability: "personnel:decide",
    minimumRiskClass: "A3",
    description: "Make a material personnel decision."
  },
  {
    type: "record.delete",
    capability: "record:delete",
    minimumRiskClass: "A4",
    description: "Delete an organizational record."
  },
  {
    type: "audit.alter",
    capability: "audit:alter",
    minimumRiskClass: "A4",
    description: "Alter or remove audit evidence."
  },
  {
    type: "governance.bypass",
    capability: "governance:bypass",
    minimumRiskClass: "A4",
    description: "Bypass a governance control."
  }
]);

function normalizeDefinition(definition) {
  if (!definition || typeof definition !== "object" || Array.isArray(definition)) {
    throw new ValidationError("Action definition must be an object.");
  }
  return immutableJson({
    type: requiredString(definition.type, "action type", {
      max: 120,
      pattern: /^[a-z][a-z0-9.-]+$/
    }),
    capability: requiredString(definition.capability, "action capability", {
      max: 120,
      pattern: /^[a-z][a-z0-9:*-]+$/
    }),
    minimumRiskClass: enumValue(
      definition.minimumRiskClass,
      "minimum risk class",
      RISK_CLASSES
    ),
    description: requiredString(definition.description, "action description", {
      max: 500
    }),
    tags: uniqueStrings(definition.tags || [], "action tags", {
      maximum: 16,
      pattern: /^[a-z][a-z0-9-]+$/
    })
  });
}

export function compareRisk(left, right) {
  enumValue(left, "risk class", RISK_CLASSES);
  enumValue(right, "risk class", RISK_CLASSES);
  return RISK_RANK[left] - RISK_RANK[right];
}

export class ActionCatalog {
  constructor(additionalDefinitions = []) {
    this.definitions = new Map();
    for (const definition of [...DEFAULT_ACTIONS, ...additionalDefinitions]) {
      const normalized = normalizeDefinition(definition);
      const existing = this.definitions.get(normalized.type);
      if (existing) {
        if (JSON.stringify(existing) !== JSON.stringify(normalized)) {
          throw new ConflictError(
            `Conflicting action definition: ${normalized.type}.`
          );
        }
        continue;
      }
      this.definitions.set(normalized.type, normalized);
    }
  }

  get(type) {
    const definition = this.definitions.get(type);
    if (!definition) {
      throw new PolicyError(`Unknown action type denied: ${type || "<empty>"}.`, {
        actionType: type || null
      });
    }
    return definition;
  }

  list() {
    return [...this.definitions.values()].map((definition) => ({
      ...definition,
      tags: [...definition.tags]
    }));
  }
}

export const defaultActionDefinitions = DEFAULT_ACTIONS;

import {
  digestObject,
  immutableJson,
  jsonClone
} from "../kernel/canonical-json.js";
import { IntegrityError, PolicyError, ValidationError } from "../kernel/errors.js";
import {
  assertPlainObject,
  enumValue,
  requiredString
} from "../kernel/validation.js";
import {
  compareRisk,
  RISK_CLASSES,
  SENSITIVITY_CLASSES
} from "./action-catalog.js";

const INTENT_VERSION = "1.0";

export function executionModeFor(riskClass) {
  enumValue(riskClass, "risk class", RISK_CLASSES);
  if (riskClass === "A0" || riskClass === "A1") return "role_authorized";
  if (riskClass === "A2") return "human_approval";
  return "blocked";
}

export function createActionIntent({
  catalog,
  actionType,
  target,
  parameters = {},
  declaredRiskClass,
  sensitivity = "internal"
}) {
  if (!catalog) throw new ValidationError("Action catalog is required.");
  const definition = catalog.get(actionType);
  const riskClass = declaredRiskClass
    ? enumValue(declaredRiskClass, "declared risk class", RISK_CLASSES)
    : definition.minimumRiskClass;

  if (compareRisk(riskClass, definition.minimumRiskClass) < 0) {
    throw new PolicyError(
      `${actionType} cannot be classified below ${definition.minimumRiskClass}.`,
      {
        actionType,
        declaredRiskClass: riskClass,
        minimumRiskClass: definition.minimumRiskClass
      }
    );
  }

  const normalizedSensitivity = enumValue(
    sensitivity,
    "sensitivity",
    SENSITIVITY_CLASSES
  );
  if (normalizedSensitivity === "restricted") {
    throw new PolicyError("Restricted data is disabled in the Level 1 runtime.");
  }

  const unsigned = {
    schemaVersion: INTENT_VERSION,
    actionType: definition.type,
    capability: definition.capability,
    target: requiredString(target, "action target", { max: 500 }),
    parametersDigest: digestObject(
      assertPlainObject(parameters, "action parameters")
    ),
    riskClass,
    sensitivity: normalizedSensitivity,
    executionMode: executionModeFor(riskClass)
  };
  return immutableJson({
    ...unsigned,
    digest: digestObject(unsigned)
  });
}

export function verifyActionIntent(intent, catalog) {
  assertPlainObject(intent, "action intent");
  if (intent.schemaVersion !== INTENT_VERSION) {
    throw new IntegrityError("Unsupported action-intent version.");
  }
  const definition = catalog.get(intent.actionType);
  if (intent.capability !== definition.capability) {
    throw new IntegrityError("Action-intent capability does not match catalogue.");
  }
  if (compareRisk(intent.riskClass, definition.minimumRiskClass) < 0) {
    throw new IntegrityError("Action intent is under-classified.");
  }
  enumValue(intent.sensitivity, "action-intent sensitivity", SENSITIVITY_CLASSES);
  if (intent.sensitivity === "restricted") {
    throw new PolicyError("Restricted data is disabled in the Level 1 runtime.");
  }
  if (intent.executionMode !== executionModeFor(intent.riskClass)) {
    throw new IntegrityError("Action-intent execution mode is invalid.");
  }
  requiredString(intent.target, "action-intent target", { max: 500 });
  requiredString(intent.parametersDigest, "action-intent parameters digest", {
    max: 80,
    pattern: /^sha256:[a-f0-9]{64}$/
  });

  const unsigned = jsonClone(intent);
  delete unsigned.digest;
  const calculated = digestObject(unsigned);
  if (intent.digest !== calculated) {
    throw new IntegrityError("Action-intent digest mismatch.");
  }
  return true;
}

import {
  digestObject,
  immutableJson,
  jsonClone
} from "../kernel/canonical-json.js";
import {
  IntegrityError,
  PolicyError,
  ValidationError
} from "../kernel/errors.js";
import { assertId } from "../kernel/ids.js";
import {
  assertPlainObject,
  enumValue,
  isoDate,
  requiredString
} from "../kernel/validation.js";
import { compareRisk } from "./action-catalog.js";
import { verifyActionIntent } from "./action-intent.js";

const DELIVERY_INTENT_SCHEMA_VERSION = "1.0";
const DELIVERY_INTENT_KIND = "fdos-connector-delivery-intent";
const DIGEST_PATTERN = /^sha256:[0-9a-f]{64}$/;
const AGENT_ID_PATTERN =
  /^agent:[a-z][a-z0-9-]{1,63}:[a-zA-Z0-9][a-zA-Z0-9._-]{1,63}$/;

const intentKeys = [
  "connector",
  "digest",
  "idempotencyDigest",
  "kind",
  "operation",
  "parameters",
  "parametersDigest",
  "requestDigest",
  "requestedAt",
  "requestedBy",
  "schemaVersion",
  "target",
  "task"
];
const connectorBindingKeys = [
  "contractDigest",
  "contractId",
  "contractVersion",
  "executionMode",
  "externalEffects",
  "id",
  "maxAttempts",
  "networkAccess"
];
const operationBindingKeys = [
  "actionType",
  "capability",
  "digest",
  "id",
  "riskClass",
  "sensitivity",
  "targetPrefix"
];
const taskBindingKeys = [
  "actionIntentDigest",
  "attempt",
  "id",
  "ownerRoleId",
  "runId"
];

function exactKeys(value, expected, field, ErrorType = ValidationError) {
  assertPlainObject(value, field);
  const actual = Object.keys(value).sort();
  const normalizedExpected = [...expected].sort();
  if (
    actual.length !== normalizedExpected.length ||
    actual.some((key, index) => key !== normalizedExpected[index])
  ) {
    throw new ErrorType(`${field} has an unexpected shape.`);
  }
}

function normalizedDigest(value, field) {
  return requiredString(value, field, {
    max: 71,
    pattern: DIGEST_PATTERN
  });
}

function normalizeConnectorBinding(source, ErrorType = ValidationError) {
  exactKeys(
    source,
    connectorBindingKeys,
    "delivery connector binding",
    ErrorType
  );
  if (
    source.executionMode !== "dry_run" ||
    source.networkAccess !== false ||
    source.externalEffects !== false
  ) {
    throw new ErrorType(
      "Delivery connector binding exceeds the dry-run boundary."
    );
  }
  if (
    !Number.isSafeInteger(source.maxAttempts) ||
    source.maxAttempts < 1 ||
    source.maxAttempts > 3
  ) {
    throw new ErrorType("Delivery connector retry budget is invalid.");
  }
  return {
    id: requiredString(source.id, "delivery connector id", {
      max: 160,
      pattern:
        /^connector:[a-z][a-z0-9-]{1,63}:[a-zA-Z0-9][a-zA-Z0-9._-]{1,63}$/
    }),
    contractId: requiredString(
      source.contractId,
      "delivery contract id",
      {
        max: 80,
        pattern: /^[a-z][a-z0-9.-]{1,79}$/
      }
    ),
    contractVersion: requiredString(
      source.contractVersion,
      "delivery contract version",
      {
        max: 80,
        pattern: /^[0-9]+\.[0-9]+\.[0-9]+(?:-[a-z0-9.-]+)?$/
      }
    ),
    contractDigest: normalizedDigest(
      source.contractDigest,
      "delivery contract digest"
    ),
    executionMode: "dry_run",
    networkAccess: false,
    externalEffects: false,
    maxAttempts: source.maxAttempts
  };
}

function normalizeOperationBinding(source, ErrorType = ValidationError) {
  exactKeys(
    source,
    operationBindingKeys,
    "delivery operation binding",
    ErrorType
  );
  const riskClass = enumValue(
    source.riskClass,
    "delivery operation risk class",
    ["A0", "A1"]
  );
  const sensitivity = enumValue(
    source.sensitivity,
    "delivery operation sensitivity",
    ["public", "internal"]
  );
  return {
    id: requiredString(source.id, "delivery operation id", {
      max: 80,
      pattern: /^[a-z][a-z0-9.-]{1,79}$/
    }),
    digest: normalizedDigest(
      source.digest,
      "delivery operation digest"
    ),
    actionType: requiredString(
      source.actionType,
      "delivery operation action type",
      {
        max: 120,
        pattern: /^[a-z][a-z0-9.-]+$/
      }
    ),
    capability: requiredString(
      source.capability,
      "delivery operation capability",
      {
        max: 120,
        pattern: /^[a-z][a-z0-9:*-]+$/
      }
    ),
    riskClass,
    sensitivity,
    targetPrefix: requiredString(
      source.targetPrefix,
      "delivery operation target prefix",
      { max: 120 }
    )
  };
}

function normalizeTaskBinding(source, ErrorType = ValidationError) {
  exactKeys(source, taskBindingKeys, "delivery task binding", ErrorType);
  if (!Number.isSafeInteger(source.attempt) || source.attempt < 1) {
    throw new ErrorType("Delivery task attempt is invalid.");
  }
  return {
    id: assertId(source.id, "delivery task id"),
    runId: assertId(source.runId, "delivery run id"),
    attempt: source.attempt,
    actionIntentDigest: normalizedDigest(
      source.actionIntentDigest,
      "delivery action-intent digest"
    ),
    ownerRoleId: requiredString(
      source.ownerRoleId,
      "delivery task owner role",
      {
        max: 64,
        pattern: /^[a-z][a-z0-9-]{1,63}$/
      }
    )
  };
}

export function createDeliveryIntent({
  actionCatalog,
  resolvedConnector,
  task,
  parameters,
  requestedBy,
  requestedAt,
  idempotencyKey
}) {
  if (!actionCatalog || !resolvedConnector) {
    throw new ValidationError(
      "Delivery intent requires action and connector registries."
    );
  }
  assertPlainObject(task, "delivery task");
  verifyActionIntent(task.actionIntent, actionCatalog);
  const { instance, contract, operation } = resolvedConnector;
  if (
    contract.executionMode !== "dry_run" ||
    contract.networkAccess !== false ||
    contract.externalEffects !== false
  ) {
    throw new PolicyError(
      "Connector delivery exceeds the dry-run experiment boundary."
    );
  }
  if (
    task.actionIntent.actionType !== operation.actionType ||
    task.actionIntent.capability !== operation.capability ||
    task.actionIntent.riskClass !== operation.riskClass ||
    task.actionIntent.sensitivity !== operation.sensitivity ||
    !task.actionIntent.target.startsWith(operation.targetPrefix)
  ) {
    throw new PolicyError(
      "Connector operation does not exactly match the task action intent."
    );
  }
  if (compareRisk(task.actionIntent.riskClass, "A2") >= 0) {
    throw new PolicyError(
      "A2–A4 connector delivery is disabled in this experiment."
    );
  }
  const normalizedRequestedBy = requiredString(
    requestedBy,
    "delivery requester",
    {
      max: 140,
      pattern: AGENT_ID_PATTERN
    }
  );
  const normalizedRequestedAt = isoDate(
    requestedAt,
    "delivery requestedAt"
  );
  const normalizedIdempotencyKey = requiredString(
    idempotencyKey,
    "delivery idempotency key",
    { max: 200 }
  );
  const normalizedParameters = immutableJson(
    jsonClone(assertPlainObject(parameters, "delivery parameters"))
  );
  const connector = {
    id: instance.id,
    contractId: contract.id,
    contractVersion: contract.version,
    contractDigest: contract.digest,
    executionMode: contract.executionMode,
    networkAccess: contract.networkAccess,
    externalEffects: contract.externalEffects,
    maxAttempts: contract.maxAttempts
  };
  const operationBinding = {
    id: operation.id,
    digest: operation.digest,
    actionType: operation.actionType,
    capability: operation.capability,
    riskClass: operation.riskClass,
    sensitivity: operation.sensitivity,
    targetPrefix: operation.targetPrefix
  };
  const taskBinding = {
    id: assertId(task.id, "delivery task id"),
    runId: assertId(task.runId, "delivery run id"),
    attempt: task.attempt,
    actionIntentDigest: task.actionIntent.digest,
    ownerRoleId: task.ownerRoleId
  };
  const parametersDigest = digestObject(normalizedParameters);
  const requestDigest = digestObject({
    connector,
    operation: operationBinding,
    task: taskBinding,
    target: task.actionIntent.target,
    parametersDigest
  });
  const unsigned = {
    schemaVersion: DELIVERY_INTENT_SCHEMA_VERSION,
    kind: DELIVERY_INTENT_KIND,
    connector,
    operation: operationBinding,
    task: taskBinding,
    target: task.actionIntent.target,
    parameters: normalizedParameters,
    parametersDigest,
    requestedBy: normalizedRequestedBy,
    requestedAt: normalizedRequestedAt,
    idempotencyDigest: digestObject({
      connectorId: instance.id,
      operationId: operation.id,
      requestedBy: normalizedRequestedBy,
      key: normalizedIdempotencyKey
    }),
    requestDigest
  };
  return immutableJson({
    ...unsigned,
    digest: digestObject(unsigned)
  });
}

export function verifyDeliveryIntent(intent) {
  exactKeys(
    intent,
    intentKeys,
    "connector delivery intent",
    IntegrityError
  );
  if (
    intent.schemaVersion !== DELIVERY_INTENT_SCHEMA_VERSION ||
    intent.kind !== DELIVERY_INTENT_KIND
  ) {
    throw new IntegrityError("Connector delivery intent is unsupported.");
  }
  const connector = normalizeConnectorBinding(intent.connector, IntegrityError);
  const operation = normalizeOperationBinding(intent.operation, IntegrityError);
  const task = normalizeTaskBinding(intent.task, IntegrityError);
  const target = requiredString(intent.target, "delivery target", {
    max: 500
  });
  if (!target.startsWith(operation.targetPrefix)) {
    throw new IntegrityError(
      "Delivery target falls outside the contracted target prefix."
    );
  }
  const parameters = jsonClone(
    assertPlainObject(intent.parameters, "delivery parameters")
  );
  const parametersDigest = normalizedDigest(
    intent.parametersDigest,
    "delivery parameters digest"
  );
  if (digestObject(parameters) !== parametersDigest) {
    throw new IntegrityError("Delivery parameter digest mismatch.");
  }
  const requestedBy = requiredString(
    intent.requestedBy,
    "delivery requester",
    {
      max: 140,
      pattern: AGENT_ID_PATTERN
    }
  );
  isoDate(intent.requestedAt, "delivery requestedAt");
  normalizedDigest(intent.idempotencyDigest, "delivery idempotency digest");
  const requestDigest = normalizedDigest(
    intent.requestDigest,
    "delivery request digest"
  );
  if (
    digestObject({
      connector,
      operation,
      task,
      target,
      parametersDigest
    }) !== requestDigest
  ) {
    throw new IntegrityError("Delivery request digest mismatch.");
  }
  const unsigned = jsonClone(intent);
  delete unsigned.digest;
  if (digestObject(unsigned) !== intent.digest) {
    throw new IntegrityError("Connector delivery-intent digest mismatch.");
  }
  return true;
}

function exactEvidence(source, expected, field) {
  exactKeys(source, expected, field);
  if (source.externalEffect !== "none") {
    throw new PolicyError(
      "Dry-run connector outcomes must declare no external effect."
    );
  }
}

export function normalizeDeliveryOutcome(type, source) {
  const normalizedType = enumValue(type, "delivery outcome", [
    "failed",
    "simulated",
    "uncertain"
  ]);
  if (normalizedType === "simulated") {
    exactEvidence(
      source,
      ["externalEffect", "resultDigest"],
      "simulated delivery evidence"
    );
    return immutableJson({
      type: normalizedType,
      evidence: {
        externalEffect: "none",
        resultDigest: normalizedDigest(
          source.resultDigest,
          "simulated result digest"
        )
      }
    });
  }
  if (normalizedType === "failed") {
    exactEvidence(
      source,
      [
        "errorCode",
        "externalEffect",
        "messageDigest",
        "retryable"
      ],
      "failed delivery evidence"
    );
    if (typeof source.retryable !== "boolean") {
      throw new ValidationError(
        "Failed delivery retryable must be a boolean."
      );
    }
    return immutableJson({
      type: normalizedType,
      evidence: {
        externalEffect: "none",
        errorCode: requiredString(
          source.errorCode,
          "delivery error code",
          {
            max: 64,
            pattern: /^[A-Z][A-Z0-9_]{2,63}$/
          }
        ),
        messageDigest: normalizedDigest(
          source.messageDigest,
          "delivery failure message digest"
        ),
        retryable: source.retryable
      }
    });
  }
  exactEvidence(
    source,
    [
      "evidenceDigest",
      "externalEffect",
      "reasonCode"
    ],
    "uncertain delivery evidence"
  );
  return immutableJson({
    type: normalizedType,
    evidence: {
      externalEffect: "none",
      reasonCode: requiredString(
        source.reasonCode,
        "delivery uncertainty reason code",
        {
          max: 64,
          pattern: /^[A-Z][A-Z0-9_]{2,63}$/
        }
      ),
      evidenceDigest: normalizedDigest(
        source.evidenceDigest,
        "delivery uncertainty evidence digest"
      )
    }
  });
}

export function verifyDeliveryOutcome(outcome) {
  exactKeys(
    outcome,
    ["evidence", "recordedAt", "recordedBy", "type"],
    "delivery outcome",
    IntegrityError
  );
  const normalized = normalizeDeliveryOutcome(
    outcome.type,
    outcome.evidence
  );
  const recordedBy = requiredString(
    outcome.recordedBy,
    "delivery outcome recorder",
    {
      max: 160,
      pattern:
        /^connector:[a-z][a-z0-9-]{1,63}:[a-zA-Z0-9][a-zA-Z0-9._-]{1,63}$/
    }
  );
  const recordedAt = isoDate(
    outcome.recordedAt,
    "delivery outcome recordedAt"
  );
  return immutableJson({
    ...normalized,
    recordedBy,
    recordedAt
  });
}

import {
  digestObject,
  immutableJson
} from "../kernel/canonical-json.js";
import {
  IntegrityError,
  ValidationError
} from "../kernel/errors.js";
import {
  assertPlainObject,
  requiredString
} from "../kernel/validation.js";

export const NO_NETWORK_ISOLATION_PROVIDER = "none";
export const DARWIN_NETWORK_ISOLATION_PROVIDER =
  "darwin-sandbox-exec-network-write-deny-v1";
const DIGEST_PATTERN = /^sha256:[0-9a-f]{64}$/;
const bindingKeys = Object.freeze([
  "policyDigest",
  "provider",
  "required"
]);
const noIsolationPolicy = Object.freeze({
  schemaVersion: "1.0",
  kind: "fdos-network-isolation-policy",
  provider: NO_NETWORK_ISOLATION_PROVIDER,
  networkIsolationEnforced: false
});
export const NO_NETWORK_ISOLATION_POLICY_DIGEST =
  digestObject(noIsolationPolicy);

function exactKeys(value, expected, field, ErrorType) {
  try {
    assertPlainObject(value, field);
  } catch (error) {
    if (ErrorType === ValidationError) throw error;
    throw new ErrorType(`${field} has an unexpected shape.`);
  }
  const actual = Object.keys(value).sort();
  const normalizedExpected = [...expected].sort();
  if (
    actual.length !== normalizedExpected.length ||
    actual.some((key, index) => key !== normalizedExpected[index])
  ) {
    throw new ErrorType(`${field} has an unexpected shape.`);
  }
}

export function normalizeNetworkIsolationBinding(
  value,
  ErrorType = ValidationError
) {
  exactKeys(
    value,
    bindingKeys,
    "worker network-isolation binding",
    ErrorType
  );
  let provider;
  let policyDigest;
  try {
    provider = requiredString(
      value.provider,
      "worker network-isolation provider",
      {
        max: 80,
        pattern: /^[a-z][a-z0-9-]{1,79}$/
      }
    );
    policyDigest = requiredString(
      value.policyDigest,
      "worker network-isolation policy digest",
      {
        max: 71,
        pattern: DIGEST_PATTERN
      }
    );
  } catch (error) {
    if (ErrorType === ValidationError) throw error;
    throw new ErrorType(
      "Worker network-isolation identity is invalid."
    );
  }
  if (
    provider === NO_NETWORK_ISOLATION_PROVIDER &&
    value.required === false &&
    policyDigest === NO_NETWORK_ISOLATION_POLICY_DIGEST
  ) {
    return immutableJson({
      required: false,
      provider,
      policyDigest
    });
  }
  if (
    provider === DARWIN_NETWORK_ISOLATION_PROVIDER &&
    value.required === true
  ) {
    return immutableJson({
      required: true,
      provider,
      policyDigest
    });
  }
  throw new ErrorType(
    "Worker network-isolation binding is inconsistent."
  );
}

export function processOnlyNetworkIsolationBinding() {
  return immutableJson({
    required: false,
    provider: NO_NETWORK_ISOLATION_PROVIDER,
    policyDigest: NO_NETWORK_ISOLATION_POLICY_DIGEST
  });
}

export function verifyNetworkIsolationBinding(value) {
  normalizeNetworkIsolationBinding(value, IntegrityError);
  return true;
}

export const DRY_RUN_WORKER_ARTIFACT_ID =
  "worker:connector-dry-run";
export const DRY_RUN_WORKER_ARTIFACT_VERSION =
  "3.0.0-experimental";
export const DRY_RUN_WORKER_ENTRYPOINT =
  "src/workers/dry-run-connector-worker.js";
export const DRY_RUN_WORKER_ARTIFACT_FILES = Object.freeze([
  "src/domain/action-catalog.js",
  "src/domain/action-intent.js",
  "src/domain/delivery-intent.js",
  "src/domain/network-isolation-contract.js",
  "src/domain/worker-identity.js",
  "src/domain/worker-package-contract.js",
  "src/domain/workload-session-contract.js",
  "src/kernel/canonical-json.js",
  "src/kernel/errors.js",
