  "src/kernel/validation.js",
  "src/workers/dry-run-connector-worker.js",
  "src/workers/dry-run-worker-protocol.js"
]);

export const DRY_RUN_WORKER_PACKAGE_ID =
  "worker-package:connector-dry-run";
export const DRY_RUN_WORKER_PACKAGE_VERSION =
  "2.0.0-experimental";

import { immutableJson } from "../kernel/canonical-json.js";
import {
  IntegrityError,
  ValidationError
} from "../kernel/errors.js";
import {
  assertPlainObject,
  requiredString
} from "../kernel/validation.js";
import {
  DRY_RUN_WORKER_ARTIFACT_ID,
  DRY_RUN_WORKER_ARTIFACT_VERSION,
  DRY_RUN_WORKER_PACKAGE_ID,
  DRY_RUN_WORKER_PACKAGE_VERSION
} from "./worker-identity.js";

const DIGEST_PATTERN = /^sha256:[0-9a-f]{64}$/;
const ISSUER_PATTERN = /^issuer:[a-z][a-z0-9._-]{1,63}$/;
const KEY_ID_PATTERN = /^key:[a-z0-9][a-z0-9._-]{1,95}$/;
const bindingKeys = Object.freeze([
  "artifactDigest",
  "artifactId",
  "artifactVersion",
  "attestationDigest",
  "issuerId",
  "keyId",
  "packageDigest",
  "packageId",
  "packageVersion",
  "trustAnchorDigest"
]);

function exactKeys(
  value,
  expected,
  field,
  ErrorType = ValidationError
) {
  try {
    assertPlainObject(value, field);
  } catch {
    throw new ErrorType(`${field} has an unexpected shape.`);
  }
  const actual = Object.keys(value).sort();
  const normalizedExpected = [...expected].sort();
  if (
    actual.length !== normalizedExpected.length ||
    actual.some((key, index) => key !== normalizedExpected[index])
  ) {
    throw new ErrorType(`${field} has an unexpected shape.`);
  }
}

function normalizedString(
  value,
  field,
  options,
  ErrorType = ValidationError
) {
  try {
    return requiredString(value, field, options);
  } catch {
    throw new ErrorType(`${field} is invalid.`);
  }
}

function normalizedDigest(
  value,
  field,
  ErrorType = ValidationError
) {
  return normalizedString(
    value,
    field,
    {
      max: 71,
      pattern: DIGEST_PATTERN
    },
    ErrorType
  );
}

export function normalizeWorkerPackageBinding(
  value,
  ErrorType = ValidationError
) {
  exactKeys(
    value,
    bindingKeys,
    "worker package binding",
    ErrorType
  );
  if (
    value.packageId !== DRY_RUN_WORKER_PACKAGE_ID ||
    value.packageVersion !== DRY_RUN_WORKER_PACKAGE_VERSION ||
    value.artifactId !== DRY_RUN_WORKER_ARTIFACT_ID ||
    value.artifactVersion !== DRY_RUN_WORKER_ARTIFACT_VERSION
  ) {
    throw new ErrorType("Worker package binding is unsupported.");
  }
  return immutableJson({
    packageId: DRY_RUN_WORKER_PACKAGE_ID,
    packageVersion: DRY_RUN_WORKER_PACKAGE_VERSION,
    packageDigest: normalizedDigest(
      value.packageDigest,
      "worker package digest",
      ErrorType
    ),
    artifactId: DRY_RUN_WORKER_ARTIFACT_ID,
    artifactVersion: DRY_RUN_WORKER_ARTIFACT_VERSION,
    artifactDigest: normalizedDigest(
      value.artifactDigest,
      "worker package artifact digest",
      ErrorType
    ),
    attestationDigest: normalizedDigest(
      value.attestationDigest,
      "worker package attestation digest",
      ErrorType
    ),
    trustAnchorDigest: normalizedDigest(
      value.trustAnchorDigest,
      "worker package trust-anchor digest",
      ErrorType
    ),
    issuerId: normalizedString(
      value.issuerId,
      "worker package issuer",
      {
        max: 71,
        pattern: ISSUER_PATTERN
      },
      ErrorType
    ),
    keyId: normalizedString(
      value.keyId,
      "worker package key id",
      {
        max: 100,
        pattern: KEY_ID_PATTERN
      },
      ErrorType
    )
  });
}

export function workerPackageBindingsEqual(left, right) {
  try {
    const normalizedLeft = normalizeWorkerPackageBinding(
      left,
      IntegrityError
    );
    const normalizedRight = normalizeWorkerPackageBinding(
      right,
      IntegrityError
    );
    return bindingKeys.every(
      (key) => normalizedLeft[key] === normalizedRight[key]
    );
  } catch {
    return false;
  }
}

import {
  createHash,
  createPublicKey,
  verify as verifyBytes
} from "node:crypto";
import {
  canonicalJson,
  digestObject,
  immutableJson,
  jsonClone
} from "../kernel/canonical-json.js";
import {
  IntegrityError,
  ValidationError
} from "../kernel/errors.js";
import {
  assertPlainObject,
  requiredString
} from "../kernel/validation.js";
import {
  normalizeWorkerPackageBinding,
  workerPackageBindingsEqual
} from "./worker-package-contract.js";

const SCHEMA_VERSION = "1.0";
const SESSION_KIND = "fdos-ephemeral-workload-session";
const ENVELOPE_KIND =
  "fdos-authenticated-worker-response";
const SIGNATURE_STATEMENT_KIND =
  "fdos-workload-response-signature-statement";
const EVIDENCE_KIND =
  "fdos-workload-session-evidence";
const OBSERVATION_KIND =
  "fdos-workload-session-observation";
const ALGORITHM = "Ed25519";
export const WORKLOAD_SESSION_MODE =
  "ephemeral-ed25519-parent-challenge";
const DIGEST_PATTERN = /^sha256:[0-9a-f]{64}$/;
const CHALLENGE_PATTERN = /^[a-zA-Z0-9_-]{43}$/;
const SIGNATURE_PATTERN = /^[a-zA-Z0-9_-]{86}$/;
const KEY_ID_PATTERN = /^key:session-[0-9a-f]{24}$/;
const sessionKeys = Object.freeze([
  "algorithm",
  "challenge",
  "keyId",
  "kind",
  "mode",
  "publicKeyPem",
  "schemaVersion",
  "workerPackage"
]);
const envelopeKeys = Object.freeze([
  "digest",
  "kind",
  "response",
  "schemaVersion",
  "signature",
  "workloadSession"
]);
const observationKeys = Object.freeze([
  "challengeDigest",
  "ephemeralKeyGeneratedByBootstrap",
  "externallyAttested",
  "keyId",
  "kind",
  "mode",
  "packageBindingDigest",
  "sessionDigest"
]);

function exactKeys(
  value,
  expected,
  field,
  ErrorType = ValidationError
) {
  try {
    assertPlainObject(value, field);
  } catch {
    throw new ErrorType(`${field} has an unexpected shape.`);
  }
  const actual = Object.keys(value).sort();
  const normalizedExpected = [...expected].sort();
  if (
    actual.length !== normalizedExpected.length ||
    actual.some(
      (key, index) => key !== normalizedExpected[index]
    )
  ) {
    throw new ErrorType(`${field} has an unexpected shape.`);
  }
}

function normalizedString(
  value,
  field,
  options,
  ErrorType = ValidationError
) {
  try {
    return requiredString(value, field, options);
  } catch {
    throw new ErrorType(`${field} is invalid.`);
  }
}

function normalizedDigest(
  value,
  field,
  ErrorType = ValidationError
) {
  return normalizedString(
    value,
    field,
    {
      max: 71,
      pattern: DIGEST_PATTERN
    },
    ErrorType
  );
}

function normalizedBase64url(
  value,
  field,
  pattern,
  byteLength,
  ErrorType = ValidationError
) {
  const normalized = normalizedString(
    value,
    field,
    {
      max: 100,
      pattern
    },
    ErrorType
  );
  const bytes = Buffer.from(normalized, "base64url");
  if (
    bytes.length !== byteLength ||
    bytes.toString("base64url") !== normalized
  ) {
    throw new ErrorType(`${field} is invalid.`);
  }
  return normalized;
}

export function normalizeWorkloadSessionChallenge(
  value,
  ErrorType = ValidationError
) {
  return normalizedBase64url(
    value,
    "workload session challenge",
    CHALLENGE_PATTERN,
    32,
    ErrorType
  );
}

function normalizedSignature(
  value,
  ErrorType = ValidationError
) {
  return normalizedBase64url(
    value,
    "workload response signature",
    SIGNATURE_PATTERN,
    64,
    ErrorType
  );
}

function normalizedPublicKey(
  value,
  ErrorType = ValidationError
) {
  const publicKeyPem = normalizedString(
    value,
    "workload session public key",
    {
      max: 2_000,
      pattern: /^-----BEGIN PUBLIC KEY-----/
    },
    ErrorType
  );
  let publicKey;
  try {
    publicKey = createPublicKey(publicKeyPem);
  } catch {
    throw new ErrorType(
      "Workload session public key is invalid."
    );
  }
  if (publicKey.asymmetricKeyType !== "ed25519") {
    throw new ErrorType(
      "Workload session public key must be Ed25519."
    );
  }
  const canonicalPublicKeyPem = publicKey
    .export({
      type: "spki",
      format: "pem"
    })
    .trim();
  if (canonicalPublicKeyPem !== publicKeyPem) {
    throw new ErrorType(
      "Workload session public key is not canonical."
    );
  }
  return {
    publicKey,
    publicKeyPem: canonicalPublicKeyPem
  };
}

function keyIdForPublicKey(publicKey) {
  const bytes = publicKey.export({
    type: "spki",
    format: "der"
  });
  const fingerprint = createHash("sha256")
    .update(bytes)
    .digest("hex");
  return `key:session-${fingerprint.slice(0, 24)}`;
}

export function workloadSessionKeyId(publicKeyPem) {
  return keyIdForPublicKey(
    normalizedPublicKey(publicKeyPem).publicKey
  );
}

export function normalizeWorkloadSession(
  value,
  ErrorType = ValidationError
) {
  exactKeys(
    value,
    sessionKeys,
    "workload session",
    ErrorType
  );
  if (
    value.schemaVersion !== SCHEMA_VERSION ||
    value.kind !== SESSION_KIND ||
    value.algorithm !== ALGORITHM ||
    value.mode !== WORKLOAD_SESSION_MODE
  ) {
    throw new ErrorType(
      "Workload session identity is unsupported."
    );
  }
  const { publicKey, publicKeyPem } = normalizedPublicKey(
    value.publicKeyPem,
    ErrorType
  );
  const keyId = normalizedString(
    value.keyId,
    "workload session key id",
    {
      max: 100,
      pattern: KEY_ID_PATTERN
    },
    ErrorType
  );
  if (keyIdForPublicKey(publicKey) !== keyId) {
    throw new ErrorType(
      "Workload session key id does not match its public key."
    );
  }
  return immutableJson({
    schemaVersion: SCHEMA_VERSION,
    kind: SESSION_KIND,
    mode: WORKLOAD_SESSION_MODE,
    algorithm: ALGORITHM,
    challenge: normalizeWorkloadSessionChallenge(
      value.challenge,
      ErrorType
    ),
    keyId,
    publicKeyPem,
    workerPackage: normalizeWorkerPackageBinding(
      value.workerPackage,
      ErrorType
    )
  });
}

export function createWorkloadSession({
  challenge,
  publicKeyPem,
  workerPackage
}) {
  const { publicKey } = normalizedPublicKey(publicKeyPem);
  return normalizeWorkloadSession({
    schemaVersion: SCHEMA_VERSION,
    kind: SESSION_KIND,
    mode: WORKLOAD_SESSION_MODE,
    algorithm: ALGORITHM,
    challenge,
    keyId: keyIdForPublicKey(publicKey),
    publicKeyPem,
    workerPackage
  });
}

export function normalizeWorkloadSessionObservation(
  value,
  ErrorType = ValidationError
) {
  exactKeys(
    value,
    observationKeys,
    "workload session observation",
    ErrorType
  );
  if (
    value.kind !== OBSERVATION_KIND ||
    value.mode !== WORKLOAD_SESSION_MODE ||
    value.ephemeralKeyGeneratedByBootstrap !== true ||
    value.externallyAttested !== false
  ) {
    throw new ErrorType(
      "Workload session observation is unsupported."
    );
  }
  return immutableJson({
    kind: OBSERVATION_KIND,
    mode: WORKLOAD_SESSION_MODE,
    keyId: normalizedString(
      value.keyId,
      "workload session observation key id",
      {
        max: 100,
        pattern: KEY_ID_PATTERN
      },
      ErrorType
    ),
    sessionDigest: normalizedDigest(
      value.sessionDigest,
      "workload session observation digest",
      ErrorType
    ),
    challengeDigest: normalizedDigest(
      value.challengeDigest,
      "workload session challenge digest",
      ErrorType
    ),
    packageBindingDigest: normalizedDigest(
      value.packageBindingDigest,
      "workload session package-binding digest",
      ErrorType
    ),
    ephemeralKeyGeneratedByBootstrap: true,
    externallyAttested: false
  });
}

export function createWorkloadSessionObservation(
  value
) {
  const workloadSession =
    normalizeWorkloadSession(value);
  return normalizeWorkloadSessionObservation({
    kind: OBSERVATION_KIND,
    mode: WORKLOAD_SESSION_MODE,
    keyId: workloadSession.keyId,
    sessionDigest: digestObject(workloadSession),
    challengeDigest: digestObject({
      challenge: workloadSession.challenge
    }),
    packageBindingDigest: digestObject(
      workloadSession.workerPackage
    ),
    ephemeralKeyGeneratedByBootstrap: true,
    externallyAttested: false
  });
}

export function verifyWorkloadSessionObservation(
  value,
  {
    expectedChallenge,
    expectedWorkerPackage
  } = {}
) {
  const observation =
    normalizeWorkloadSessionObservation(
      value,
      IntegrityError
    );
  const challenge = normalizeWorkloadSessionChallenge(
    expectedChallenge,
    IntegrityError
  );
  const workerPackage = normalizeWorkerPackageBinding(
    expectedWorkerPackage,
    IntegrityError
  );
  if (
    observation.challengeDigest !==
      digestObject({ challenge }) ||
    observation.packageBindingDigest !==
      digestObject(workerPackage)
  ) {
    throw new IntegrityError(
      "Workload session observation differs from its request."
    );
  }
  return true;
}

function normalizedResponseReference(
  value,
  ErrorType = ValidationError
) {
  try {
    assertPlainObject(value, "worker response");
  } catch {
    throw new ErrorType(
      "Authenticated worker response has an invalid payload."
    );
  }
  const requestDigest = normalizedDigest(
    value.requestDigest,
    "authenticated worker request digest",
    ErrorType
  );
  const digest = normalizedDigest(
    value.digest,
    "authenticated worker response digest",
    ErrorType
  );
  try {
    const normalized = jsonClone(value);
    const unsigned = jsonClone(normalized);
    delete unsigned.digest;
    if (digestObject(unsigned) !== digest) {
      throw new Error(
        "Worker response digest mismatch."
      );
    }
    return {
      ...normalized,
      requestDigest,
      digest
    };
  } catch {
    throw new ErrorType(
      "Authenticated worker response digest is invalid."
    );
  }
}

export function createWorkloadResponseSignatureRequest({
  response,
  workloadSession
}) {
  const normalizedResponse =
    normalizedResponseReference(response);
  const normalizedSession =
    normalizeWorkloadSession(workloadSession);
  return immutableJson({
    schemaVersion: SCHEMA_VERSION,
    kind: SIGNATURE_STATEMENT_KIND,
    sessionDigest: digestObject(normalizedSession),
    requestDigest: normalizedResponse.requestDigest,
    responseDigest: normalizedResponse.digest
  });
}

export function createAuthenticatedWorkerResponse({
  response,
  workloadSession,
  signature
}) {
  const normalizedResponse =
    normalizedResponseReference(response);
  const normalizedSession =
    normalizeWorkloadSession(workloadSession);
  createWorkloadResponseSignatureRequest({
    response: normalizedResponse,
    workloadSession: normalizedSession
  });
  const unsigned = {
    schemaVersion: SCHEMA_VERSION,
    kind: ENVELOPE_KIND,
    workloadSession: normalizedSession,
    response: normalizedResponse,
    signature: normalizedSignature(signature)
  };
  return immutableJson({
    ...unsigned,
    digest: digestObject(unsigned)
  });
}

export function normalizeAuthenticatedWorkerResponse(
  value,
  ErrorType = IntegrityError
) {
  exactKeys(
    value,
    envelopeKeys,
    "authenticated worker response",
    ErrorType
  );
  if (
    value.schemaVersion !== SCHEMA_VERSION ||
    value.kind !== ENVELOPE_KIND
  ) {
    throw new ErrorType(
      "Authenticated worker response is unsupported."
    );
  }
  const workloadSession = normalizeWorkloadSession(
    value.workloadSession,
    ErrorType
  );
  const response = normalizedResponseReference(
    value.response,
    ErrorType
  );
  const signature = normalizedSignature(
    value.signature,
    ErrorType
  );
  const unsigned = {
    schemaVersion: SCHEMA_VERSION,
    kind: ENVELOPE_KIND,
    workloadSession,
    response,
    signature
  };
  const digest = normalizedDigest(
    value.digest,
    "authenticated worker response envelope digest",
    ErrorType
  );
  if (digestObject(unsigned) !== digest) {
    throw new ErrorType(
      "Authenticated worker response envelope digest mismatch."
    );
  }
  return immutableJson({
    ...unsigned,
    digest
  });
}

export function verifyAuthenticatedWorkerResponse(
  value,
  {
    expectedChallenge,
    expectedWorkerPackage
  } = {}
) {
  const envelope = normalizeAuthenticatedWorkerResponse(
    value,
    IntegrityError
  );
  const challenge = normalizeWorkloadSessionChallenge(
    expectedChallenge,
    IntegrityError
  );
  const workerPackage = normalizeWorkerPackageBinding(
    expectedWorkerPackage,
    IntegrityError
  );
  if (
    envelope.workloadSession.challenge !== challenge ||
    !workerPackageBindingsEqual(
      envelope.workloadSession.workerPackage,
      workerPackage
    )
  ) {
    throw new IntegrityError(
      "Workload session does not bind the exact request."
    );
  }
  const statement = createWorkloadResponseSignatureRequest({
    response: envelope.response,
    workloadSession: envelope.workloadSession
  });
  const publicKey = createPublicKey(
    envelope.workloadSession.publicKeyPem
  );
  const valid = verifyBytes(
    null,
    Buffer.from(canonicalJson(statement), "utf8"),
    publicKey,
    Buffer.from(envelope.signature, "base64url")
  );
  if (!valid) {
    throw new IntegrityError(
      "Workload response signature verification failed."
    );
  }
  const observation = createWorkloadSessionObservation(
    envelope.workloadSession
  );
  return immutableJson({
    kind: EVIDENCE_KIND,
    mode: observation.mode,
    algorithm: ALGORITHM,
    keyId: observation.keyId,
    sessionDigest: observation.sessionDigest,
    challengeDigest: observation.challengeDigest,
    packageBindingDigest:
      observation.packageBindingDigest,
    responseEnvelopeDigest: envelope.digest,
    responseSignatureVerified: true,
    challengeMatched: true,
    packageBindingMatched: true,
    externallyAttested: false
  });
}

import { createHash } from "node:crypto";
import { ValidationError } from "./errors.js";

function normalizedJson(value, path, seen) {
  if (value === null) return null;

  if (typeof value === "string" || typeof value === "boolean") {
    return value;
  }

  if (typeof value === "number") {
    if (!Number.isFinite(value)) {
      throw new ValidationError(`Non-finite number at ${path}.`);
    }
    return Object.is(value, -0) ? 0 : value;
  }

  if (
    typeof value === "undefined" ||
    typeof value === "function" ||
    typeof value === "symbol" ||
    typeof value === "bigint"
  ) {
    throw new ValidationError(`Unsupported JSON value at ${path}.`);
  }

  if (seen.has(value)) {
    throw new ValidationError(`Circular JSON value at ${path}.`);
  }
  seen.add(value);

  try {
    if (Array.isArray(value)) {
      return value.map((entry, index) =>
        normalizedJson(entry, `${path}[${index}]`, seen)
      );
    }

    const prototype = Object.getPrototypeOf(value);
    if (prototype !== Object.prototype && prototype !== null) {
      throw new ValidationError(`Non-plain JSON object at ${path}.`);
    }

    const result = {};
    for (const key of Object.keys(value).sort()) {
      result[key] = normalizedJson(value[key], `${path}.${key}`, seen);
    }
    return result;
  } finally {
    seen.delete(value);
  }
}

export function canonicalJson(value) {
  return JSON.stringify(normalizedJson(value, "$", new Set()));
}

export function sha256(value) {
  return createHash("sha256").update(value, "utf8").digest("hex");
}

export function digestObject(value) {
  return `sha256:${sha256(canonicalJson(value))}`;
}

export function jsonClone(value) {
  return JSON.parse(canonicalJson(value));
}

export function deepFreeze(value) {
  if (!value || typeof value !== "object" || Object.isFrozen(value)) {
    return value;
  }
  Object.freeze(value);
  for (const entry of Object.values(value)) {
    deepFreeze(entry);
  }
  return value;
}

export function immutableJson(value) {
  return deepFreeze(jsonClone(value));
}

export class FdosError extends Error {
  constructor(message, { code = "FDOS_ERROR", cause, details } = {}) {
    super(message, { cause });
    this.name = new.target.name;
    this.code = code;
    this.details = details || null;
  }
}

export class ValidationError extends FdosError {
  constructor(message, details) {
    super(message, { code: "VALIDATION_ERROR", details });
  }
}

export class AuthorizationError extends FdosError {
  constructor(message, details) {
    super(message, { code: "AUTHORIZATION_DENIED", details });
  }
}

export class ConflictError extends FdosError {
  constructor(message, details) {
    super(message, { code: "STATE_CONFLICT", details });
  }
}

export class IntegrityError extends FdosError {
  constructor(message, details) {
    super(message, { code: "INTEGRITY_ERROR", details });
  }
}

export class PersistenceError extends FdosError {
  constructor(message, details) {
    super(message, { code: "PERSISTENCE_ERROR", details });
  }
}

export class NotFoundError extends FdosError {
  constructor(message, details) {
    super(message, { code: "NOT_FOUND", details });
  }
}

export class PolicyError extends FdosError {
  constructor(message, details) {
    super(message, { code: "POLICY_DENIED", details });
  }
}

import { randomUUID } from "node:crypto";
import { ValidationError } from "./errors.js";

const ID_PATTERN = /^[a-z][a-z0-9-]{1,31}_[a-zA-Z0-9][a-zA-Z0-9_-]{5,95}$/;
const PREFIX_PATTERN = /^[a-z][a-z0-9-]{1,31}$/;

export function createId(prefix) {
  if (!PREFIX_PATTERN.test(prefix)) {
    throw new ValidationError(`Invalid identifier prefix: ${prefix}.`);
  }
  return `${prefix}_${randomUUID().replaceAll("-", "")}`;
}

export function assertId(value, field = "identifier") {
  if (typeof value !== "string" || !ID_PATTERN.test(value)) {
    throw new ValidationError(`Invalid ${field}.`);
  }
  return value;
}

export function deterministicIdFactory(namespace = "test") {
  let sequence = 0;
  return (prefix) => {
    sequence += 1;
    return `${prefix}_${namespace}_${String(sequence).padStart(6, "0")}`;
  };
}

import { ValidationError } from "./errors.js";

export function requiredString(
  value,
  field,
  { min = 1, max = 4_000, pattern } = {}
) {
  if (typeof value !== "string") {
    throw new ValidationError(`${field} must be a string.`);
  }
  const normalized = value.trim();
  if (
    normalized.length < min ||
    normalized.length > max ||
    (pattern && !pattern.test(normalized))
  ) {
    throw new ValidationError(`${field} is invalid.`);
  }
  return normalized;
}

export function optionalString(value, field, options = {}) {
  if (value === undefined || value === null) return null;
  return requiredString(value, field, options);
}

export function uniqueStrings(
  value,
  field,
  { maximum = 32, pattern } = {}
) {
  if (!Array.isArray(value)) {
    throw new ValidationError(`${field} must be a list.`);
  }
  const normalized = value.map((entry, index) =>
    requiredString(entry, `${field}[${index}]`, { max: 200, pattern })
  );
  if (normalized.length > maximum || new Set(normalized).size !== normalized.length) {
    throw new ValidationError(`${field} contains duplicates or too many values.`);
  }
  return normalized;
}

export function enumValue(value, field, allowed) {
  if (!allowed.includes(value)) {
    throw new ValidationError(
      `${field} must be one of: ${allowed.join(", ")}.`
    );
  }
  return value;
}

export function isoDate(value, field) {
  if (
    typeof value !== "string" ||
    !Number.isFinite(Date.parse(value)) ||
    new Date(value).toISOString() !== value
  ) {
    throw new ValidationError(`${field} must be an ISO-8601 timestamp.`);
  }
  return value;
}

export function assertPlainObject(value, field) {
  if (
    !value ||
    typeof value !== "object" ||
    Array.isArray(value) ||
    (Object.getPrototypeOf(value) !== Object.prototype &&
      Object.getPrototypeOf(value) !== null)
  ) {
    throw new ValidationError(`${field} must be a plain object.`);
  }
  return value;
}

import { canonicalJson } from "../kernel/canonical-json.js";
import { open } from "node:fs/promises";
import { connect, createServer } from "node:net";
import {
  createDryRunWorkerResponse,
  verifyDryRunWorkerRequest
} from "./dry-run-worker-protocol.js";
import {
  DARWIN_NETWORK_ISOLATION_PROVIDER,
  NO_NETWORK_ISOLATION_PROVIDER
} from "../domain/network-isolation-contract.js";
import {
  normalizeWorkerPackageBinding,
  workerPackageBindingsEqual
} from "../domain/worker-package-contract.js";
import {
  createWorkloadSessionObservation,
  normalizeWorkloadSession
} from "../domain/workload-session-contract.js";

const MAX_INPUT_BYTES = 64 * 1024;
const FAULT_MODES = new Set([
  "none",
  "crash-before-response",
  "hang",
  "response-then-crash",
  "session-observation-mismatch"
]);
let input = "";
let inputBytes = 0;
let stopped = false;
const NETWORK_DENIAL_CODES = new Set(["EACCES", "EPERM"]);
const NETWORK_PROBE_TIMEOUT_MS = 500;

function stop(code, reasonCode) {
  if (stopped) return;
  stopped = true;
  if (reasonCode) {
    process.stderr.write(`${reasonCode}\n`);
  }
  process.exit(code);
}

process.on("uncaughtException", () => {
  stop(70, "WORKER_UNEXPECTED_FAILURE");
});

process.on("unhandledRejection", () => {
  stop(70, "WORKER_UNEXPECTED_FAILURE");
});

process.stdin.setEncoding("utf8");
process.stdin.on("data", (chunk) => {
  if (stopped) return;
  inputBytes += Buffer.byteLength(chunk, "utf8");
  if (inputBytes > MAX_INPUT_BYTES) {
    stop(65, "WORKER_INPUT_TOO_LARGE");
    return;
  }
  input += chunk;
});

function probeListenDenied() {
  return new Promise((resolve, reject) => {
    const server = createServer();
    let settled = false;
    const timer = setTimeout(() => {
      if (settled) return;
      settled = true;
      try {
        server.close();
      } catch {}
      server.unref();
      reject(new Error("Network listen probe timed out."));
    }, NETWORK_PROBE_TIMEOUT_MS);
    server.once("error", (error) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      if (NETWORK_DENIAL_CODES.has(error?.code)) {
        resolve();
        return;
      }
      reject(new Error("Network listen probe was not denied."));
    });
    server.once("listening", () => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      server.close(() => {
        reject(new Error("Network listen unexpectedly succeeded."));
      });
    });
    server.listen({
      host: "127.0.0.1",
      port: 0,
      exclusive: true
    });
  });
}

function probeConnectDenied() {
  return new Promise((resolve, reject) => {
    const socket = connect({
      host: "127.0.0.1",
      port: 9
    });
    let settled = false;
    let timer;
    const finish = (error) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      socket.destroy();
      if (error) reject(error);
      else resolve();
    };
    timer = setTimeout(() => {
      finish(new Error("Network connect probe timed out."));
    }, NETWORK_PROBE_TIMEOUT_MS);
    socket.once("error", (error) => {
      if (NETWORK_DENIAL_CODES.has(error?.code)) {
        finish();
        return;
      }
      finish(new Error("Network connect probe was not denied."));
    });
    socket.once("connect", () => {
      finish(new Error("Network connect unexpectedly succeeded."));
    });
  });
}

async function probeFilesystemWriteDenied() {
  try {
    const handle = await open("/dev/null", "w");
    await handle.close();
  } catch (error) {
    if (NETWORK_DENIAL_CODES.has(error?.code)) return;
    throw new Error(
      "Filesystem write-open probe was not denied predictably."
    );
  }
  throw new Error("Filesystem write-open unexpectedly succeeded.");
}

async function isolationAttestation(request) {
  const binding = request.execution.networkIsolation;
  const environmentProvider =
    process.env.FDOS_NETWORK_ISOLATION_PROVIDER || "";
  const environmentPolicyDigest =
    process.env.FDOS_NETWORK_ISOLATION_POLICY_DIGEST || "";
  if (
    environmentProvider !== binding.provider ||
    environmentPolicyDigest !== binding.policyDigest
  ) {
    throw new Error("Worker isolation environment differs from request.");
  }
  if (!binding.required) {
    if (binding.provider !== NO_NETWORK_ISOLATION_PROVIDER) {
      throw new Error("Worker process-only isolation is inconsistent.");
    }
    return {
      enforced: false,
      filesystemWriteEnforced: false,
      filesystemWriteProbe: "not_run",
      provider: binding.provider,
      policyDigest: binding.policyDigest,
      probe: "not_run"
    };
  }
  if (binding.provider !== DARWIN_NETWORK_ISOLATION_PROVIDER) {
    throw new Error("Worker network-isolation provider is unsupported.");
  }
  await probeListenDenied();
  await probeConnectDenied();
  await probeFilesystemWriteDenied();
  return {
    enforced: true,
    filesystemWriteEnforced: true,
    filesystemWriteProbe: "dev_null_write_open_denied",
    provider: binding.provider,
    policyDigest: binding.policyDigest,
    probe: "socket_listen_and_connect_denied"
  };
}

function workerPackageObservation(request) {
  const expected = request.execution.workerPackage;
  const source =
    globalThis.__FDOS_VERIFIED_WORKER_PACKAGE__;
  if (
    !source ||
    source.packageDigestMatched !== true ||
    source.releaseSignatureVerifiedByBootstrap !== true ||
    source.evaluatedFromVerifiedMemory !== true
  ) {
    throw new Error(
      "Worker package was not verified before evaluation."
    );
  }
  const observed = normalizeWorkerPackageBinding({
    packageId: source.packageId,
    packageVersion: source.packageVersion,
    packageDigest: source.packageDigest,
    artifactId: source.artifactId,
    artifactVersion: source.artifactVersion,
    artifactDigest: source.artifactDigest,
    attestationDigest: source.attestationDigest,
    trustAnchorDigest: source.trustAnchorDigest,
    issuerId: source.issuerId,
    keyId: source.keyId
  });
  if (
    !workerPackageBindingsEqual(observed, expected)
  ) {
    throw new Error(
      "Worker package differs from its signed request binding."
    );
  }
  return {
    ...observed,
    packageDigestMatched: true,
    releaseSignatureVerifiedByBootstrap: true,
    evaluatedFromVerifiedMemory: true
  };
}

function workloadSessionForRequest(request) {
  const source =
    globalThis.__FDOS_WORKLOAD_SESSION__;
  const signResponse =
    globalThis.__FDOS_SIGN_WORKER_RESPONSE__;
  if (!source || typeof signResponse !== "function") {
    throw new Error(
      "Worker workload session is unavailable."
    );
  }
  const workloadSession =
    normalizeWorkloadSession(source);
  if (
    workloadSession.challenge !==
      request.execution.workloadSessionChallenge ||
    !workerPackageBindingsEqual(
      workloadSession.workerPackage,
      request.execution.workerPackage
    )
  ) {
    throw new Error(
      "Worker workload session differs from its request."
    );
  }
  return {
    workloadSession,
    signResponse
  };
}

function workloadSessionObservationForResponse(
  workloadSession,
  faultMode
) {
  const observation =
    createWorkloadSessionObservation(workloadSession);
  if (faultMode !== "session-observation-mismatch") {
    return observation;
  }
  const prefix = "key:session-";
  const fingerprint = observation.keyId.slice(
    prefix.length
  );
  return {
    ...observation,
    keyId:
      `${prefix}` +
      `${fingerprint.startsWith("0") ? "1" : "0"}` +
      fingerprint.slice(1)
  };
}

async function handleInput() {
  if (stopped) return;
  const faultMode =
    process.env.FDOS_DRY_RUN_WORKER_FAULT || "none";
  if (!FAULT_MODES.has(faultMode)) {
    stop(64, "WORKER_FAULT_MODE_INVALID");
    return;
  }
  try {
    const source = input.trim();
    if (!source || source.includes("\n") || source.includes("\r")) {
      stop(65, "WORKER_INPUT_SHAPE_INVALID");
      return;
    }
    const request = JSON.parse(source);
    if (canonicalJson(request) !== source) {
      stop(65, "WORKER_INPUT_NOT_CANONICAL");
      return;
    }
    const now = new Date().toISOString();
    verifyDryRunWorkerRequest(request, { now });
    const packageObservation =
      workerPackageObservation(request);
    const workloadSession =
      workloadSessionForRequest(request);
    const networkIsolationAttestation =
      await isolationAttestation(request);

    if (faultMode === "crash-before-response") {
      stop(71, "WORKER_INJECTED_CRASH");
      return;
    }
    if (faultMode === "hang") {
      setInterval(() => {}, 1_000);
      return;
    }

    const response = createDryRunWorkerResponse({
      request,
      completedAt: new Date().toISOString(),
      networkIsolationAttestation,
      workerPackageObservation: packageObservation,
      workloadSessionObservation:
        workloadSessionObservationForResponse(
          workloadSession.workloadSession,
          faultMode
        )
    });
    const authenticatedResponse =
      workloadSession.signResponse(response);
    process.stdout.write(
      `${canonicalJson(authenticatedResponse)}\n`,
      () => {
        if (faultMode === "response-then-crash") {
          stop(
            72,
            "WORKER_INJECTED_POST_RESPONSE_CRASH"
          );
          return;
        }
        stop(0);
      }
    );
  } catch {
    stop(65, "WORKER_INPUT_REJECTED");
  }
}

process.stdin.on("end", () => {
  handleInput().catch(() => {
    stop(70, "WORKER_UNEXPECTED_FAILURE");
  });
});

process.stdin.resume();

import {
  digestObject,
  immutableJson,
  jsonClone
} from "../kernel/canonical-json.js";
import {
  IntegrityError,
  PolicyError,
  ValidationError
} from "../kernel/errors.js";
import { assertId } from "../kernel/ids.js";
import {
  assertPlainObject,
  isoDate,
  requiredString
} from "../kernel/validation.js";
import {
  normalizeDeliveryOutcome,
  verifyDeliveryIntent
} from "../domain/delivery-intent.js";
import {
  NO_NETWORK_ISOLATION_PROVIDER,
  normalizeNetworkIsolationBinding,
  processOnlyNetworkIsolationBinding
} from "../domain/network-isolation-contract.js";
import {
  normalizeWorkerPackageBinding,
  workerPackageBindingsEqual
} from "../domain/worker-package-contract.js";
import {
  normalizeWorkloadSessionChallenge,
  normalizeWorkloadSessionObservation,
  verifyWorkloadSessionObservation
} from "../domain/workload-session-contract.js";

const PROTOCOL_SCHEMA_VERSION = "1.4";
const REQUEST_KIND = "fdos-process-worker-request";
const RESPONSE_KIND = "fdos-process-worker-response";
const MAX_REQUEST_TTL_MS = 5 * 60 * 1_000;
const DIGEST_PATTERN = /^sha256:[0-9a-f]{64}$/;
const CONNECTOR_ID_PATTERN =
  /^connector:[a-z][a-z0-9-]{1,63}:[a-zA-Z0-9][a-zA-Z0-9._-]{1,63}$/;
const requestKeys = Object.freeze([
  "claimId",
  "connectorId",
  "deliveryId",
  "digest",
  "execution",
  "expiresAt",
  "intent",
  "issuedAt",
  "kind",
  "requestId",
  "schemaVersion"
]);
const executionKeys = Object.freeze([
  "externalEffects",
  "mode",
  "networkAccess",
  "networkIsolation",
  "workerPackage",
  "workloadSessionChallenge"
]);
const responseKeys = Object.freeze([
  "claimId",
  "completedAt",
  "connectorId",
  "deliveryId",
  "digest",
  "kind",
  "outcome",
  "requestDigest",
  "requestId",
  "schemaVersion",
  "workerBoundary"
]);
const workerBoundaryKeys = Object.freeze([
  "externalEffects",
  "filesystemWriteIsolationEnforced",
  "filesystemWriteIsolationProbe",
  "networkAccess",
  "networkIsolationEnforced",
  "networkIsolationPolicyDigest",
  "networkIsolationProbe",
  "networkIsolationProvider",
  "processSeparated",
  "shell",
  "workerPackage",
  "workloadSession"
]);
const isolationAttestationKeys = Object.freeze([
  "enforced",
  "filesystemWriteEnforced",
  "filesystemWriteProbe",
  "policyDigest",
  "probe",
  "provider"
]);
const packageObservationKeys = Object.freeze([
  "artifactDigest",
  "artifactId",
  "artifactVersion",
  "attestationDigest",
  "evaluatedFromVerifiedMemory",
  "issuerId",
  "keyId",
  "packageDigest",
  "packageDigestMatched",
  "packageId",
  "packageVersion",
  "releaseSignatureVerifiedByBootstrap",
  "trustAnchorDigest"
]);

function exactKeys(value, expected, field, ErrorType = ValidationError) {
  try {
    assertPlainObject(value, field);
  } catch (error) {
    if (ErrorType === ValidationError) throw error;
    throw new ErrorType(`${field} has an unexpected shape.`);
  }
  const actual = Object.keys(value).sort();
  const normalizedExpected = [...expected].sort();
  if (
    actual.length !== normalizedExpected.length ||
    actual.some((key, index) => key !== normalizedExpected[index])
  ) {
    throw new ErrorType(`${field} has an unexpected shape.`);
  }
}

function normalizedDigest(value, field, ErrorType = ValidationError) {
  try {
    return requiredString(value, field, {
      max: 71,
      pattern: DIGEST_PATTERN
    });
  } catch (error) {
    if (ErrorType === ValidationError) throw error;
    throw new ErrorType(`${field} is invalid.`);
  }
}

function normalizedId(value, field, prefix, ErrorType = ValidationError) {
  try {
    const id = assertId(value, field);
    if (!id.startsWith(prefix)) {
      throw new ValidationError(`${field} has the wrong prefix.`);
    }
    return id;
  } catch (error) {
    if (ErrorType === ValidationError) throw error;
    throw new ErrorType(`${field} is invalid.`);
  }
}

function normalizeExecution(value, ErrorType = ValidationError) {
  exactKeys(value, executionKeys, "worker execution boundary", ErrorType);
  if (
    value.mode !== "dry_run" ||
    value.networkAccess !== false ||
    value.externalEffects !== false
  ) {
    throw new ErrorType(
      "Worker request exceeds the no-network dry-run boundary."
    );
  }
  return {
    mode: "dry_run",
    networkAccess: false,
    externalEffects: false,
    networkIsolation: normalizeNetworkIsolationBinding(
      value.networkIsolation,
      ErrorType
    ),
    workerPackage: normalizeWorkerPackageBinding(
      value.workerPackage,
      ErrorType
    ),
    workloadSessionChallenge:
      normalizeWorkloadSessionChallenge(
        value.workloadSessionChallenge,
        ErrorType
      )
  };
}

function normalizeRequest(request, ErrorType = ValidationError) {
  exactKeys(request, requestKeys, "worker request", ErrorType);
  if (
    request.schemaVersion !== PROTOCOL_SCHEMA_VERSION ||
    request.kind !== REQUEST_KIND
  ) {
    throw new ErrorType("Worker request protocol is unsupported.");
  }
  const requestId = normalizedId(
    request.requestId,
    "worker request id",
    "workerrequest_",
    ErrorType
  );
  const deliveryId = normalizedId(
    request.deliveryId,
    "worker delivery id",
    "delivery_",
    ErrorType
  );
  const claimId = normalizedId(
    request.claimId,
    "worker claim id",
    "claim_",
    ErrorType
  );
  let connectorId;
  try {
    connectorId = requiredString(
      request.connectorId,
      "worker connector id",
      {
        max: 160,
        pattern: CONNECTOR_ID_PATTERN
      }
    );
  } catch (error) {
    if (ErrorType === ValidationError) throw error;
    throw new ErrorType("Worker connector id is invalid.");
  }
  try {
    verifyDeliveryIntent(request.intent);
  } catch (error) {
    if (ErrorType === ValidationError) throw error;
    throw new ErrorType("Worker delivery intent is invalid.");
  }
  if (
    request.intent.connector.id !== connectorId ||
    request.intent.connector.executionMode !== "dry_run" ||
    request.intent.connector.networkAccess !== false ||
    request.intent.connector.externalEffects !== false
  ) {
    throw new ErrorType(
      "Worker request and delivery intent boundary differ."
    );
  }
  let issuedAt;
  let expiresAt;
  try {
    issuedAt = isoDate(request.issuedAt, "worker request issuedAt");
    expiresAt = isoDate(request.expiresAt, "worker request expiresAt");
  } catch (error) {
    if (ErrorType === ValidationError) throw error;
    throw new ErrorType("Worker request time binding is invalid.");
  }
  const ttl = Date.parse(expiresAt) - Date.parse(issuedAt);
  if (ttl <= 0 || ttl > MAX_REQUEST_TTL_MS) {
    throw new ErrorType("Worker request validity window is invalid.");
  }
  const execution = normalizeExecution(request.execution, ErrorType);
  const unsigned = {
    schemaVersion: PROTOCOL_SCHEMA_VERSION,
    kind: REQUEST_KIND,
    requestId,
    deliveryId,
    claimId,
    connectorId,
    issuedAt,
    expiresAt,
    execution,
    intent: jsonClone(request.intent)
  };
  const digest = normalizedDigest(
    request.digest,
    "worker request digest",
    ErrorType
  );
  if (digestObject(unsigned) !== digest) {
    throw new ErrorType("Worker request digest mismatch.");
  }
  return immutableJson({ ...unsigned, digest });
}

function normalizeWorkerBoundary(value, ErrorType = IntegrityError) {
  exactKeys(
    value,
    workerBoundaryKeys,
    "worker response boundary",
    ErrorType
  );
  const isolation = normalizeNetworkIsolationBinding(
    {
      required: value.networkIsolationEnforced,
      provider: value.networkIsolationProvider,
      policyDigest: value.networkIsolationPolicyDigest
    },
    ErrorType
  );
  const expectedProbe = isolation.required
    ? "socket_listen_and_connect_denied"
    : "not_run";
  const expectedFilesystemProbe = isolation.required
    ? "dev_null_write_open_denied"
    : "not_run";
  const workerPackage = normalizeWorkerPackageObservation(
    value.workerPackage,
    ErrorType
  );
  const workloadSession =
    normalizeWorkloadSessionObservation(
      value.workloadSession,
      ErrorType
    );
  if (
    value.processSeparated !== true ||
    value.shell !== false ||
    value.networkAccess !== false ||
    value.externalEffects !== false ||
    value.networkIsolationProbe !== expectedProbe ||
    value.filesystemWriteIsolationEnforced !== isolation.required ||
    value.filesystemWriteIsolationProbe !== expectedFilesystemProbe
  ) {
    throw new ErrorType("Worker response boundary is inconsistent.");
  }
  return {
    processSeparated: true,
    shell: false,
    networkAccess: false,
    externalEffects: false,
    filesystemWriteIsolationEnforced: isolation.required,
    filesystemWriteIsolationProbe: expectedFilesystemProbe,
    networkIsolationEnforced: isolation.required,
    networkIsolationProvider: isolation.provider,
    networkIsolationPolicyDigest: isolation.policyDigest,
    networkIsolationProbe: expectedProbe,
    workerPackage,
    workloadSession
  };
}

function normalizeWorkerPackageObservation(
  value,
  ErrorType = IntegrityError
) {
  exactKeys(
    value,
    packageObservationKeys,
    "worker package observation",
    ErrorType
  );
  if (
    value.packageDigestMatched !== true ||
    value.releaseSignatureVerifiedByBootstrap !== true ||
    value.evaluatedFromVerifiedMemory !== true
  ) {
    throw new ErrorType(
      "Worker package was not verified before evaluation."
    );
  }
  const binding = normalizeWorkerPackageBinding(
    {
      packageId: value.packageId,
      packageVersion: value.packageVersion,
      packageDigest: value.packageDigest,
      artifactId: value.artifactId,
      artifactVersion: value.artifactVersion,
      artifactDigest: value.artifactDigest,
      attestationDigest: value.attestationDigest,
      trustAnchorDigest: value.trustAnchorDigest,
      issuerId: value.issuerId,
      keyId: value.keyId
    },
    ErrorType
  );
  return {
    ...binding,
    packageDigestMatched: true,
    releaseSignatureVerifiedByBootstrap: true,
    evaluatedFromVerifiedMemory: true
  };
}

function packageObservationMatchesBinding(observation, binding) {
  const observedBinding = {
    packageId: observation.packageId,
    packageVersion: observation.packageVersion,
    packageDigest: observation.packageDigest,
    artifactId: observation.artifactId,
    artifactVersion: observation.artifactVersion,
    artifactDigest: observation.artifactDigest,
    attestationDigest: observation.attestationDigest,
    trustAnchorDigest: observation.trustAnchorDigest,
    issuerId: observation.issuerId,
    keyId: observation.keyId
  };
  return (
    observation.packageDigestMatched === true &&
    observation.releaseSignatureVerifiedByBootstrap === true &&
    observation.evaluatedFromVerifiedMemory === true &&
    workerPackageBindingsEqual(observedBinding, binding)
  );
}

function createWorkerBoundary(
  requestIsolation,
  networkIsolationAttestation,
  requestPackage,
  workerPackageObservation,
  requestWorkloadSessionChallenge,
  workloadSessionObservation
) {
  const source =
    networkIsolationAttestation ??
    (requestIsolation.required
      ? null
      : {
          enforced: false,
          filesystemWriteEnforced: false,
          filesystemWriteProbe: "not_run",
          provider: NO_NETWORK_ISOLATION_PROVIDER,
          policyDigest: requestIsolation.policyDigest,
          probe: "not_run"
        });
  exactKeys(
    source,
    isolationAttestationKeys,
    "worker network-isolation attestation"
  );
  const boundary = normalizeWorkerBoundary(
    {
      processSeparated: true,
      shell: false,
      networkAccess: false,
      externalEffects: false,
      filesystemWriteIsolationEnforced:
        source.filesystemWriteEnforced,
      filesystemWriteIsolationProbe:
        source.filesystemWriteProbe,
      networkIsolationEnforced: source.enforced,
      networkIsolationProvider: source.provider,
      networkIsolationPolicyDigest: source.policyDigest,
      networkIsolationProbe: source.probe,
      workerPackage: workerPackageObservation,
      workloadSession: workloadSessionObservation
    },
    ValidationError
  );
  if (
    boundary.networkIsolationEnforced !== requestIsolation.required ||
    boundary.networkIsolationProvider !== requestIsolation.provider ||
    boundary.networkIsolationPolicyDigest !==
      requestIsolation.policyDigest
  ) {
    throw new PolicyError(
      "Worker network-isolation attestation differs from the request."
    );
  }
  if (
    !packageObservationMatchesBinding(
      boundary.workerPackage,
      requestPackage
    )
  ) {
    throw new PolicyError(
      "Worker package observation differs from the request."
    );
  }
  try {
    verifyWorkloadSessionObservation(
      boundary.workloadSession,
      {
        expectedChallenge:
          requestWorkloadSessionChallenge,
        expectedWorkerPackage: requestPackage
      }
    );
  } catch {
    throw new PolicyError(
      "Worker workload session differs from the request."
    );
  }
  return boundary;
}

function normalizeResponse(response, ErrorType = IntegrityError) {
  exactKeys(response, responseKeys, "worker response", ErrorType);
  if (
    response.schemaVersion !== PROTOCOL_SCHEMA_VERSION ||
    response.kind !== RESPONSE_KIND
  ) {
    throw new ErrorType("Worker response protocol is unsupported.");
  }
  const requestId = normalizedId(
    response.requestId,
    "worker response request id",
    "workerrequest_",
    ErrorType
  );
  const deliveryId = normalizedId(
    response.deliveryId,
    "worker response delivery id",
    "delivery_",
    ErrorType
  );
  const claimId = normalizedId(
    response.claimId,
    "worker response claim id",
    "claim_",
    ErrorType
  );
  let connectorId;
  let completedAt;
  try {
    connectorId = requiredString(
      response.connectorId,
      "worker response connector id",
      {
        max: 160,
        pattern: CONNECTOR_ID_PATTERN
      }
    );
    completedAt = isoDate(
      response.completedAt,
      "worker response completedAt"
    );
  } catch (error) {
    throw new ErrorType("Worker response identity or time is invalid.");
  }
  const requestDigest = normalizedDigest(
    response.requestDigest,
    "worker response request digest",
    ErrorType
  );
  let outcome;
  try {
    exactKeys(
      response.outcome,
      ["evidence", "type"],
      "worker response outcome",
      ErrorType
    );
    outcome = normalizeDeliveryOutcome(
      response.outcome.type,
      response.outcome.evidence
    );
  } catch (error) {
    if (error instanceof ErrorType) throw error;
    throw new ErrorType("Worker response outcome is invalid.");
  }
  if (outcome.type !== "simulated") {
    throw new ErrorType(
      "Process worker may return only a simulated outcome."
    );
  }
  const workerBoundary = normalizeWorkerBoundary(
    response.workerBoundary,
    ErrorType
  );
  const unsigned = {
    schemaVersion: PROTOCOL_SCHEMA_VERSION,
    kind: RESPONSE_KIND,
    requestId,
    deliveryId,
    claimId,
    connectorId,
    requestDigest,
    completedAt,
    outcome,
    workerBoundary
  };
  const digest = normalizedDigest(
    response.digest,
    "worker response digest",
    ErrorType
  );
  if (digestObject(unsigned) !== digest) {
    throw new ErrorType("Worker response digest mismatch.");
  }
  return immutableJson({ ...unsigned, digest });
}

export function createDryRunWorkerRequest({
  delivery,
  requestId,
  issuedAt,
  expiresAt,
  networkIsolation = processOnlyNetworkIsolationBinding(),
  workerPackage,
  workloadSessionChallenge
}) {
  assertPlainObject(delivery, "claimed connector delivery");
  if (
    delivery.status !== "claimed" ||
    !delivery.claim ||
    delivery.claim.connectorId !== delivery.intent?.connector?.id
  ) {
    throw new PolicyError(
      "Process worker requires one active claimed connector delivery."
    );
  }
  verifyDeliveryIntent(delivery.intent);
  if (
    delivery.intent.connector.executionMode !== "dry_run" ||
    delivery.intent.connector.networkAccess !== false ||
    delivery.intent.connector.externalEffects !== false
  ) {
    throw new PolicyError(
      "Process worker accepts only no-network, no-effect dry-run intents."
    );
  }
  const unsigned = {
    schemaVersion: PROTOCOL_SCHEMA_VERSION,
    kind: REQUEST_KIND,
    requestId: normalizedId(
      requestId,
      "worker request id",
      "workerrequest_"
    ),
    deliveryId: normalizedId(
      delivery.id,
      "worker delivery id",
      "delivery_"
    ),
    claimId: normalizedId(
      delivery.claim.id,
      "worker claim id",
      "claim_"
    ),
    connectorId: requiredString(
      delivery.intent.connector.id,
      "worker connector id",
      {
        max: 160,
        pattern: CONNECTOR_ID_PATTERN
      }
    ),
    issuedAt: isoDate(issuedAt, "worker request issuedAt"),
    expiresAt: isoDate(expiresAt, "worker request expiresAt"),
    execution: {
      mode: "dry_run",
      networkAccess: false,
      externalEffects: false,
      networkIsolation: normalizeNetworkIsolationBinding(
        networkIsolation
      ),
      workerPackage: normalizeWorkerPackageBinding(
        workerPackage
      ),
      workloadSessionChallenge:
        normalizeWorkloadSessionChallenge(
          workloadSessionChallenge
        )
    },
    intent: jsonClone(delivery.intent)
  };
  return normalizeRequest({
    ...unsigned,
    digest: digestObject(unsigned)
  });
}

export function verifyDryRunWorkerRequest(request, { now } = {}) {
  const normalized = normalizeRequest(request, IntegrityError);
  if (now !== undefined) {
    const normalizedNow = isoDate(now, "worker verification time");
    if (
      Date.parse(normalizedNow) < Date.parse(normalized.issuedAt) ||
      Date.parse(normalizedNow) > Date.parse(normalized.expiresAt)
    ) {
      throw new PolicyError("Worker request is outside its validity window.");
    }
  }
  return true;
}

export function createDryRunWorkerResponse({
  request,
  completedAt,
  networkIsolationAttestation,
  workerPackageObservation,
  workloadSessionObservation
}) {
  const normalizedRequest = normalizeRequest(request, IntegrityError);
  const normalizedCompletedAt = isoDate(
    completedAt,
    "worker response completedAt"
  );
  if (
    Date.parse(normalizedCompletedAt) <
      Date.parse(normalizedRequest.issuedAt) ||
    Date.parse(normalizedCompletedAt) >
      Date.parse(normalizedRequest.expiresAt)
  ) {
    throw new PolicyError(
      "Worker response falls outside the request validity window."
    );
  }
  const workerBoundary = createWorkerBoundary(
    normalizedRequest.execution.networkIsolation,
    networkIsolationAttestation,
    normalizedRequest.execution.workerPackage,
    workerPackageObservation,
    normalizedRequest.execution
      .workloadSessionChallenge,
    workloadSessionObservation
  );
  const outcome = normalizeDeliveryOutcome("simulated", {
    externalEffect: "none",
    resultDigest: digestObject({
      requestDigest: normalizedRequest.digest,
      intentDigest: normalizedRequest.intent.digest,
      operationDigest: normalizedRequest.intent.operation.digest,
      completedAt: normalizedCompletedAt,
      workerBoundary,
      simulated: true,
      externalEffect: "none"
    })
  });
  const unsigned = {
    schemaVersion: PROTOCOL_SCHEMA_VERSION,
    kind: RESPONSE_KIND,
    requestId: normalizedRequest.requestId,
    deliveryId: normalizedRequest.deliveryId,
    claimId: normalizedRequest.claimId,
    connectorId: normalizedRequest.connectorId,
    requestDigest: normalizedRequest.digest,
    completedAt: normalizedCompletedAt,
    outcome,
    workerBoundary
  };
  return normalizeResponse({
    ...unsigned,
    digest: digestObject(unsigned)
  });
}

export function verifyDryRunWorkerResponse(response, request) {
  const normalizedRequest = normalizeRequest(request, IntegrityError);
  const normalizedResponse = normalizeResponse(response, IntegrityError);
  verifyWorkloadSessionObservation(
    normalizedResponse.workerBoundary.workloadSession,
    {
      expectedChallenge:
        normalizedRequest.execution
          .workloadSessionChallenge,
      expectedWorkerPackage:
        normalizedRequest.execution.workerPackage
    }
  );
  if (
    normalizedResponse.requestId !== normalizedRequest.requestId ||
    normalizedResponse.deliveryId !== normalizedRequest.deliveryId ||
    normalizedResponse.claimId !== normalizedRequest.claimId ||
    normalizedResponse.connectorId !== normalizedRequest.connectorId ||
    normalizedResponse.requestDigest !== normalizedRequest.digest ||
    normalizedResponse.workerBoundary.networkIsolationEnforced !==
      normalizedRequest.execution.networkIsolation.required ||
    normalizedResponse.workerBoundary.networkIsolationProvider !==
      normalizedRequest.execution.networkIsolation.provider ||
    normalizedResponse.workerBoundary.networkIsolationPolicyDigest !==
      normalizedRequest.execution.networkIsolation.policyDigest ||
    !packageObservationMatchesBinding(
      normalizedResponse.workerBoundary.workerPackage,
      normalizedRequest.execution.workerPackage
    ) ||
    Date.parse(normalizedResponse.completedAt) <
      Date.parse(normalizedRequest.issuedAt) ||
    Date.parse(normalizedResponse.completedAt) >
      Date.parse(normalizedRequest.expiresAt)
  ) {
    throw new IntegrityError(
      "Worker response does not bind the exact request."
    );
  }
  return true;
}
